import gthLogo from '../../../../assets/public-data/gth-logo.png';
import ghanaMap from '../../../../assets/public-data/share/share-preview-ghana-map.svg';
import { SHARE_CARD } from './data/shareData.js';

/*
 * SharePreviewCard — "T8 · Share preview card (OG 1200×630)" (Figma 8500:217 / 8500:2433 / 8515:751): the image a shared link unfurls into.
 * Drawn once on a 1200×630 canvas and scaled to `width` (504 in the share dialog, 540 in the unfurl spec, 96 in the phone sheet).
 * The real Open Graph image is generated by the backend (⚠️ not built: the card here is the on-screen preview of it).
 * Props: width (px), title / headline / sub (default: the national snapshot), className.
 */

const CANVAS_W = 1200;
const CANVAS_H = 630;

const SharePreviewCard = ({
  width = 504,
  title = SHARE_CARD.title,
  headline = SHARE_CARD.headline,
  sub = SHARE_CARD.sub,
  className,
}) => {
  const scale = width / CANVAS_W;
  return (
    <div
      aria-hidden="true"
      className={className}
      style={{ width, height: Math.round(CANVAS_H * scale), position: 'relative', flexShrink: 0 }}
    >
      <div
        className="absolute top-0 left-0 overflow-hidden bg-[#2a5730] font-sans"
        style={{
          width: CANVAS_W,
          height: CANVAS_H,
          transform: `scale(${scale})`,
          transformOrigin: '0 0',
        }}
      >
        <img
          src={ghanaMap}
          alt=""
          width="360"
          height="526"
          className="absolute top-[52px] left-[781px] h-[526px] w-[360px]"
        />
        <div className="absolute top-[81px] left-[72px] flex w-[620px] flex-col gap-[14px]">
          <div className="flex items-center gap-[14px]">
            <img src={gthLogo} alt="" width="64" height="60" className="h-[60px] w-[64px]" />
            <span className="text-[28px] leading-[33px] font-bold whitespace-nowrap text-white">
              {SHARE_CARD.brand}
            </span>
          </div>
          <span className="text-[56px] leading-[67px] font-semibold tracking-[-0.83px] whitespace-nowrap text-white">
            {title}
          </span>
          <span className="text-[88px] leading-[105px] font-bold tracking-[-2.64px] whitespace-nowrap text-[#c1d4c4]">
            {headline}
          </span>
          <span className="text-[24px] leading-[29px] font-medium whitespace-nowrap text-[#c1d4c4]">
            {sub}
          </span>
        </div>
      </div>
    </div>
  );
};

export default SharePreviewCard;
